     1	import { PrismaClient } from '@prisma/client';
     2	import bcrypt from 'bcryptjs';
     3	import { seatLabel } from '../src/utils/helpers';
     4	
     5	const prisma = new PrismaClient();
     6	
     7	function buildSeats(rows: number, cols: number) {
     8	  const seats = [];
     9	  for (let r = 0; r < rows; r++) {
    10	    for (let c = 0; c < cols; c++) {
    11	      seats.push({ row: r, col: c, label: seatLabel(r, c) });
    12	    }
    13	  }
    14	  return seats;
    15	}
    16	
    17	function daysFromNow(days: number) {
    18	  const d = new Date();
    19	  d.setDate(d.getDate() + days);
    20	  d.setHours(18, 30, 0, 0);
    21	  return d;
    22	}
    23	
    24	async function main() {
    25	  const existing = await prisma.user.count();
    26	  if (existing > 0) {
    27	    console.log('Database already seeded, skipping');
    28	    return;
    29	  }
    30	
    31	  const passwordHash = await bcrypt.hash('password123', 10);
    32	
    33	  const organizer = await prisma.user.create({
    34	    data: { email: 'organizer@seatbook.test', name: 'Karim Rahman', passwordHash, role: 'ORGANIZER' },
    35	  });
    36	  const alice = await prisma.user.create({
    37	    data: { email: 'alice@seatbook.test', name: 'Alice Karim', passwordHash },
    38	  });
    39	  const bob = await prisma.user.create({
    40	    data: { email: 'bob@seatbook.test', name: 'Bob Hossain', passwordHash },
    41	  });
    42	
    43	  const talk = await prisma.event.create({
    44	    data: {
    45	      title: 'Postgres in Practice',
    46	      description: 'An evening talk on indexes, query plans and the mistakes we keep making.',
    47	      venue: 'Banani Hall, Room 2',
    48	      startsAt: daysFromNow(7),
    49	      rows: 5,
    50	      cols: 8,
    51	      priceCents: 1500,
    52	      organizerId: organizer.id,
    53	      seats: { create: buildSeats(5, 8) },
    54	    },
    55	    include: { seats: true },
    56	  });
    57	
    58	  await prisma.event.create({
    59	    data: {
    60	      title: 'Design Systems Workshop',
    61	      description: 'Hands-on workshop. Bring a laptop.',
    62	      venue: 'Gulshan Studio',
    63	      startsAt: daysFromNow(14),
    64	      rows: 4,
    65	      cols: 6,
    66	      priceCents: 4000,
    67	      organizerId: organizer.id,
    68	      seats: { create: buildSeats(4, 6) },
    69	    },
    70	  });
    71	
    72	  const past = await prisma.event.create({
    73	    data: {
    74	      title: 'Intro to TypeScript',
    75	      description: 'Already happened. Kept for history.',
    76	      venue: 'Banani Hall, Room 1',
    77	      startsAt: daysFromNow(-10),
    78	      rows: 3,
    79	      cols: 5,
    80	      priceCents: 0,
    81	      organizerId: organizer.id,
    82	      seats: { create: buildSeats(3, 5) },
    83	    },
    84	    include: { seats: true },
    85	  });
    86	
    87	  await prisma.booking.create({ data: { seatId: talk.seats[0].id, userId: alice.id } });
    88	  await prisma.booking.create({ data: { seatId: talk.seats[1].id, userId: bob.id } });
    89	  await prisma.booking.create({
    90	    data: { seatId: talk.seats[2].id, userId: bob.id, status: 'CANCELLED', cancelledAt: new Date() },
    91	  });
    92	  await prisma.booking.create({ data: { seatId: past.seats[3].id, userId: alice.id } });
    93	
    94	  console.log('Seeded users, events and bookings');
    95	}
    96	
    97	main()
    98	  .catch((err) => {
    99	    console.error(err);
   100	    process.exit(1);
   101	  })
   102	  .finally(() => prisma.$disconnect());
