===== src/middleware/auth.ts
     1	import { Request, Response, NextFunction } from 'express';
     2	import jwt from 'jsonwebtoken';
     3	
     4	const JWT_SECRET = process.env.JWT_SECRET || 'seatbook-secret-123';
     5	
     6	export interface AuthUser {
     7	  id: number;
     8	  email: string;
     9	  role: 'ORGANIZER' | 'ATTENDEE';
    10	}
    11	
    12	export interface AuthRequest extends Request {
    13	  user?: AuthUser;
    14	}
    15	
    16	export function requireAuth(req: AuthRequest, res: Response, next: NextFunction) {
    17	  const header = req.headers.authorization;
    18	  if (!header) {
    19	    return res.status(401).json({ error: 'Not logged in' });
    20	  }
    21	
    22	  const token = header.replace('Bearer ', '');
    23	  try {
    24	    const payload = jwt.verify(token, JWT_SECRET) as AuthUser;
    25	    req.user = payload;
    26	    next();
    27	  } catch (err) {
    28	    return res.status(401).json({ message: 'Invalid token' });
    29	  }
    30	}
