     8	router.post('/register', async (req, res) => {
     9	  try {
    10	    const { email, password, name, role } = req.body;
    11	
    12	    if (!email || !password || !name) {
    13	      return res.status(400).json({ error: 'email, password and name are required' });
    14	    }
    15	
    16	    const passwordHash = await bcrypt.hash(password, 10);
    17	    const user = await prisma.user.create({
    18	      data: {
    19	        email,
    20	        name,
    21	        passwordHash,
    22	        role: role === 'ORGANIZER' ? 'ORGANIZER' : 'ATTENDEE',
    23	      },
