    25	
    26	    const token = jwt.sign({ id: user.id, email: user.email, role: user.role }, 'seatbook-secret-123', {
    27	      expiresIn: '7d',
    28	    });
    29	
    30	    res.status(201).json({ token, user: { id: user.id, email: user.email, name: user.name, role: user.role } });
    31	  } catch (err: any) {
    32	    res.status(400).json({ error: err.message });
    33	  }
    34	});
    35	
    36	router.post('/login', async (req, res) => {
    37	  const { email, password } = req.body;
    38	
    39	  const user = await prisma.user.findUnique({ where: { email } });
    40	  if (!user) {
    41	    return res.status(401).json({ message: 'Invalid credentials' });
    42	  }
