===== src/routes/bookings.ts
     1	import { Router } from 'express';
     2	import prisma from '../db';
     3	import { requireAuth, AuthRequest } from '../middleware/auth';
     4	import { formatPrice } from '../utils/helpers';
     5	
     6	const router = Router();
     7	
     8	router.post('/', requireAuth, async (req: AuthRequest, res) => {
     9	  try {
    10	    const { seatId } = req.body;
    11	
    12	    const seat = await prisma.seat.findUnique({
    13	      where: { id: Number(seatId) },
    14	      include: { event: true },
    15	    });
    16	
    17	    if (!seat) {
    18	      return res.status(404).json({ error: 'Seat not found' });
    19	    }
    20	
    21	    if (seat.event.startsAt < new Date()) {
    22	      return res.status(400).json({ msg: 'This event has already started' });
    23	    }
    24	
    25	    const existing = await prisma.booking.findFirst({
    26	      where: { seatId: seat.id, status: 'CONFIRMED' },
    27	    });
    28	
    29	    if (existing) {
    30	      return res.status(409).json({ error: 'Seat already booked' });
    31	    }
    32	
    33	    const booking = await prisma.booking.create({
    34	      data: {
    35	        seatId: seat.id,
    36	        userId: req.user!.id,
    37	        status: 'CONFIRMED',
    38	      },
    39	    });
    40	
    41	    res.status(201).json(booking);
    42	  } catch (err: any) {
    43	    res.status(500).json({ error: err.message });
    44	  }
    45	});
    46	
    47	router.get('/mine', requireAuth, async (req: AuthRequest, res) => {
    48	  try {
    49	    const bookings = await prisma.booking.findMany({
    50	      where: { userId: req.user!.id },
    51	      orderBy: { createdAt: 'desc' },
    52	      include: { seat: { include: { event: true } } },
    53	    });
    54	
    55	    res.json(
    56	      bookings.map((b) => ({
    57	        id: b.id,
    58	        status: b.status,
    59	        createdAt: b.createdAt,
    60	        seat: b.seat.label,
    61	        event: {
    62	          id: b.seat.event.id,
    63	          title: b.seat.event.title,
    64	          venue: b.seat.event.venue,
    65	          startsAt: b.seat.event.startsAt,
    66	          price: formatPrice(b.seat.event.priceCents),
    67	        },
    68	      }))
    69	    );
    70	  } catch (err) {
    71	    console.log(err);
    72	    res.json([]);
    73	  }
    74	});
    75	
    76	router.post('/:id/cancel', requireAuth, async (req: AuthRequest, res) => {
    77	  const id = parseInt(req.params.id);
    78	
    79	  await prisma.booking.updateMany({
    80	    where: { id, status: 'CONFIRMED' },
    81	    data: { status: 'CANCELLED', cancelledAt: new Date() },
    82	  });
    83	
    84	  res.json({ success: true });
    85	});
    86	
    87	export default router;
