     4	import { getEventWithSeats, listEvents } from '../services/eventService';
     5	import { formatPrice, seatLabel } from '../utils/helpers';
     6	
     7	const router = Router();
     8	
     9	router.get('/', async (req, res) => {
    10	  const events = await listEvents();
    11	  res.json(events);
    12	});
    13	
    14	router.get('/:id', async (req, res) => {
    15	  const event = await getEventWithSeats(req);
    16	
    17	  if (!event) {
    18	    return res.json({ success: false, message: 'Event not found' });
    19	  }
    20	
    21	  const seats = event.seats.map((seat) => ({
    22	    id: seat.id,
    23	    row: seat.row,
    24	    col: seat.col,
    25	    label: seat.label,
