  const keys = [seatKey(hold.seat.eventId, hold.seatId), userKey(hold.seat.eventId, userId)] as const;

  const claimed = await withRedis(() => redis.beginConfirm(...keys, token, CONFIRM_GRACE_MS));
  if (!claimed) {
    await prisma.booking.updateMany({ where: { id: holdId, status: 'HELD' }, data: { status: 'EXPIRED' } });
    throw new HttpError(410, 'Your hold expired. The seat is back on sale.');
  }

  try {
    const updated = await prisma.booking.updateMany({
      where: { id: holdId, userId, status: 'HELD' },
      data: { status: 'CONFIRMED', confirmedAt: new Date() },
    });
    if (updated.count === 0) {
      throw new HttpError(410, 'This hold has ended. The seat is back on sale.');
    }
  } catch (err) {
    if (isUniqueViolation(err)) {
      await prisma.booking.update({ where: { id: holdId }, data: { status: 'RELEASED' } });
      throw new HttpError(409, 'Seat already booked');
    }
    throw err;
  }

  await redis.releaseHold(...keys, token).catch((err) => console.error('Releasing confirmed hold failed:', err));

  return prisma.booking.findUniqueOrThrow({ where: { id: holdId } });
}

export async function releaseHold(userId: number, holdId: number) {
  const hold = await prisma.booking.findFirst({
    where: { id: holdId, userId, status: 'HELD' },
    include: { seat: true },
  });
  if (!hold || !hold.holdToken) {
    throw new HttpError(404, 'Hold not found');
  }

  const keys = [seatKey(hold.seat.eventId, hold.seatId), userKey(hold.seat.eventId, userId)] as const;
  await withRedis(() => redis.releaseHold(...keys, hold.holdToken!));
  await prisma.booking.updateMany({ where: { id: holdId, status: 'HELD' }, data: { status: 'RELEASED' } });
}

export async function getMyHolds(userId: number) {
  const holds = await prisma.booking.findMany({
    where: { userId, status: 'HELD', expiresAt: { gt: new Date() } },
    orderBy: { expiresAt: 'asc' },
    include: { seat: { include: { event: true } } },
  });

  return holds.map((h) => ({
    holdId: h.id,
    seatId: h.seatId,
    label: h.seat.label,
    expiresAt: h.expiresAt,
    event: {
      id: h.seat.event.id,
      title: h.seat.event.title,
      venue: h.seat.event.venue,
      startsAt: h.seat.event.startsAt,
    },
  }));
}

// The viewer's live hold on this event, if the Redis lock still backs it.
export async function getMyHoldForEvent(userId: number, eventId: number, heldTokens: Map<number, string>) {
  const hold = await prisma.booking.findFirst({
    where: { userId, status: 'HELD', expiresAt: { gt: new Date() }, seat: { eventId } },
    include: { seat: true },
  });
  if (!hold || heldTokens.get(hold.seatId) !== hold.holdToken) {
    return null;
  }
  return { holdId: hold.id, seatId: hold.seatId, label: hold.seat.label, expiresAt: hold.expiresAt };
}

// Seat id -> token of whoever holds it right now. Reads fail soft: if Redis is down the seat map
// still renders (from the database alone) and holding a seat returns 503.
export async function getHeldSeats(seats: { id: number; eventId: number }[]): Promise<Map<number, string>> {
  const held = new Map<number, string>();
  if (seats.length === 0) {
    return held;
  }

  try {
    const tokens = await redis.mget(seats.map((s) => seatKey(s.eventId, s.id)));
    tokens.forEach((token, i) => {
      if (token) held.set(seats[i].id, token);
    });
  } catch (err) {
    console.error('Reading seat holds failed:', err);
  }
  return held;
}

// Redis frees the seat the moment a hold expires. This only tidies the database records.
export function startHoldSweeper() {
  const timer = setInterval(() => {
    prisma.booking
      .updateMany({
        where: { status: 'HELD', expiresAt: { lt: new Date(Date.now() - SWEEP_GRACE_MS) } },
        data: { status: 'EXPIRED' },
      })
      .catch((err) => console.error('Hold sweep failed:', err));
  }, SWEEP_EVERY_MS);
  timer.unref();
}

