// End-to-end checks for seat holds against the running docker compose stack.
import { execSync } from 'node:child_process';

const API = 'http://localhost:4000';
const COMPOSE_DIR = process.argv[2];
let failures = 0;

function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
}

async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}

async function login(email) {
  const { data } = await call('POST', '/auth/login', null, { email, password: 'password123' });
  return data.token;
}

function redisCli(args) {
  return execSync(`docker compose exec -T redis redis-cli ${args}`, { cwd: COMPOSE_DIR }).toString().trim();
}

const alice = await login('alice@seatbook.test');
const bob = await login('bob@seatbook.test');
const organizer = await login('organizer@seatbook.test');

// Clear any live holds left by an earlier run.
for (const t of [alice, bob]) {
  const { data } = await call('GET', '/holds/mine', t);
  for (const h of data.holds) await call('DELETE', `/holds/${h.holdId}`, t);
}

const events = (await call('GET', '/events')).data;
const event = events.find((e) => new Date(e.startsAt) > new Date() && e.seatsLeft >= 6);
const detail = (await call('GET', `/events/${event.id}`)).data;
const free = detail.seats.filter((s) => s.status === 'available');
const [s1, s2, s3, s4, s5] = free;
console.log(`Using event ${event.id} "${event.title}", seats ${[s1, s2, s3, s4, s5].map((s) => s.label).join(', ')}\n`);

// 1. Race: 20 parallel holds on one seat from two users.
const race = await Promise.all(
  Array.from({ length: 20 }, (_, i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s1.id }))
);
const winners = race.filter((r) => r.status === 201);
check('20 parallel holds on one seat -> exactly one wins', winners.length === 1, `201s=${winners.length}, others=${[...new Set(race.filter((r) => r.status !== 201).map((r) => r.status))]}`);
const winnerToken = winners[0].data && race.indexOf(winners[0]) % 2 ? bob : alice;
const loserToken = winnerToken === alice ? bob : alice;
const hold1 = winners[0].data;
check('hold expires about 10 minutes out', Math.abs(new Date(hold1.expiresAt) - new Date(hold1.serverTime) - 600000) < 2000);

// 2. One hold per user per event.
const second = await call('POST', '/holds', winnerToken, { seatId: s2.id });
check('second hold by same user on same event -> 409', second.status === 409, second.data.error);

// 3. Seat map views.
const winnerView = (await call('GET', `/events/${event.id}`, winnerToken)).data;
const loserView = (await call('GET', `/events/${event.id}`, loserToken)).data;
const anonView = (await call('GET', `/events/${event.id}`)).data;
check('holder sees heldByYou + myHold', winnerView.seats.find((s) => s.id === s1.id).status === 'heldByYou' && winnerView.myHold?.holdId === hold1.holdId);
check('other user sees held', loserView.seats.find((s) => s.id === s1.id).status === 'held' && loserView.myHold === null);
check('anonymous sees held', anonView.seats.find((s) => s.id === s1.id).status === 'held');
const listed = (await call('GET', '/events')).data.find((e) => e.id === event.id);
check('seatsLeft drops by one while held', listed.seatsLeft === event.seatsLeft - 1, `${event.seatsLeft} -> ${listed.seatsLeft}`);

// 4. Direct booking cannot steal a held seat; other user cannot confirm it.
const steal = await call('POST', '/bookings', loserToken, { seatId: s1.id });
check('direct booking of a held seat -> 409', steal.status === 409, steal.data.error);
const foreignConfirm = await call('POST', `/holds/${hold1.holdId}/confirm`, loserToken);
check("confirming someone else's hold -> 404", foreignConfirm.status === 404);
const foreignRelease = await call('DELETE', `/holds/${hold1.holdId}`, loserToken);
check("releasing someone else's hold -> 404", foreignRelease.status === 404);

// 5. Confirm.
const confirmed = await call('POST', `/holds/${hold1.holdId}/confirm`, winnerToken);
check('confirm own hold -> CONFIRMED', confirmed.status === 200 && confirmed.data.status === 'CONFIRMED');
const again = await call('POST', `/holds/${hold1.holdId}/confirm`, winnerToken);
check('confirm twice is harmless', again.status === 200 && again.data.status === 'CONFIRMED');
check('redis locks removed after confirm', redisCli(`--scan --pattern 'hold:{event:${event.id}}:*'`) === '');
const afterConfirm = (await call('GET', `/events/${event.id}`)).data;
check('seat shows booked', afterConfirm.seats.find((s) => s.id === s1.id).status === 'booked');
const reHold = await call('POST', '/holds', loserToken, { seatId: s1.id });
check('holding a booked seat -> 409', reHold.status === 409, reHold.data.error);
const mine = (await call('GET', '/bookings/mine', winnerToken)).data;
check('confirmed booking appears in My Bookings', mine.some((b) => b.id === hold1.holdId && b.status === 'CONFIRMED'));

// 6. Release.
const h2 = (await call('POST', '/holds', alice, { seatId: s2.id })).data;
const rel = await call('DELETE', `/holds/${h2.holdId}`, alice);
check('release own hold -> 204', rel.status === 204);
check('released seat is available again', (await call('GET', `/events/${event.id}`)).data.seats.find((s) => s.id === s2.id).status === 'available');
const relConfirm = await call('POST', `/holds/${h2.holdId}/confirm`, alice);
check('confirm after release -> 410', relConfirm.status === 410, relConfirm.data.error);

// 7. Expiry: make the Redis lock run out instead of waiting 10 minutes.
const h3 = (await call('POST', '/holds', bob, { seatId: s3.id })).data;
redisCli(`PEXPIRE 'hold:{event:${event.id}}:seat:${s3.id}' 1`);
redisCli(`PEXPIRE 'hold:{event:${event.id}}:user:3' 1`);
await new Promise((r) => setTimeout(r, 50));
check('expired seat is available to others at once', (await call('GET', `/events/${event.id}`)).data.seats.find((s) => s.id === s3.id).status === 'available');
const late = await call('POST', `/holds/${h3.holdId}/confirm`, bob);
check('confirm after expiry -> 410', late.status === 410, late.data.error);
const takeOver = await call('POST', '/holds', alice, { seatId: s3.id });
check('someone else can hold the expired seat', takeOver.status === 201);
if (takeOver.status === 201) await call('DELETE', `/holds/${takeOver.data.holdId}`, alice);

// 8. Who may hold.
check('logged out hold -> 401', (await call('POST', '/holds', null, { seatId: s4.id })).status === 401);
check('organizer hold -> 403', (await call('POST', '/holds', organizer, { seatId: s4.id })).status === 403);
check('organizer direct booking -> 403', (await call('POST', '/bookings', organizer, { seatId: s4.id })).status === 403);

// 9. Bad input no longer crashes the server.
check('GET /events/abc -> 400', (await call('GET', '/events/abc')).status === 400);
check('GET /events/999999 -> 404', (await call('GET', '/events/999999')).status === 404);
check('hold with bad seatId -> 400', (await call('POST', '/holds', alice, { seatId: 'x' })).status === 400);
check('hold on missing seat -> 404', (await call('POST', '/holds', alice, { seatId: 99999999 })).status === 404);
check('server still up', (await call('GET', '/health')).status === 200);

// 10. Race on direct booking.
const bookRace = await Promise.all(
  Array.from({ length: 20 }, (_, i) => call('POST', '/bookings', i % 2 ? bob : alice, { seatId: s4.id }))
);
check('20 parallel direct bookings -> exactly one wins', bookRace.filter((r) => r.status === 201).length === 1);

// 11. The database index is the last line of defence.
const dup = execSync(
  `docker compose exec -T db psql -U seatbook -tA -c "INSERT INTO \\"Booking\\" (\\"seatId\\", \\"userId\\", status) VALUES (${s4.id}, 2, 'CONFIRMED')" 2>&1 || true`,
  { cwd: COMPOSE_DIR }
).toString();
check('DB rejects a second CONFIRMED row for a seat', dup.includes('Booking_seatId_confirmed_key'));

console.log(`\n${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
