check('confirm after release -> 410', relConfirm.status === 410, relConfirm.data.error);

// 7. Expiry: make the Redis lock run out instead of waiting 10 minutes.
const h3 = (await call('POST', '/holds', bob, { seatId: s3.id })).data;
redisCli(`PEXPIRE 'hold:{event:${event.id}}:seat:${s3.id}' 1`);
redisCli(`PEXPIRE 'hold:{event:${event.id}}:user:3' 1`);
await new Promise((r) => setTimeout(r, 50));
check('expired seat is available to others at once', (await call('GET', `/events/${event.id}`)).data.seats.find((s) => s.id === s3.id).status === 'available');
const late = await call('POST', `/holds/${h3.holdId}/confirm`, bob);
check('confirm after expiry -> 410', late.status === 410, late.data.error);
const takeOver = await call('POST', '/holds', alice, { seatId: s3.id });
check('someone else can hold the expired seat', takeOver.status === 201);
if (takeOver.status === 201) await call('DELETE', `/holds/${takeOver.data.holdId}`, alice);

// 8. Who may hold.
check('logged out hold -> 401', (await call('POST', '/holds', null, { seatId: s4.id })).status === 401);
check('organizer hold -> 403', (await call('POST', '/holds', organizer, { seatId: s4.id })).status === 403);
check('organizer direct booking -> 403', (await call('POST', '/bookings', organizer, { seatId: s4.id })).status === 403);

// 9. Bad input no longer crashes the server.
check('GET /events/abc -> 400', (await call('GET', '/events/abc')).status === 400);
check('GET /events/999999 -> 404', (await call('GET', '/events/999999')).status === 404);
check('hold with bad seatId -> 400', (await call('POST', '/holds', alice, { seatId: 'x' })).status === 400);
check('hold on missing seat -> 404', (await call('POST', '/holds', alice, { seatId: 99999999 })).status === 404);
check('server still up', (await call('GET', '/health')).status === 200);

// 10. Race on direct booking.
const bookRace = await Promise.all(
  Array.from({ length: 20 }, (_, i) => call('POST', '/bookings', i % 2 ? bob : alice, { seatId: s4.id }))
);
check('20 parallel direct bookings -> exactly one wins', bookRace.filter((r) => r.status === 201).length === 1);

// 11. The database index is the last line of defence.
const dup = execSync(
  `docker compose exec -T db psql -U seatbook -tA -c "INSERT INTO \\"Booking\\" (\\"seatId\\", \\"userId\\", status) VALUES (${s4.id}, 2, 'CONFIRMED')" 2>&1 || true`,
  { cwd: COMPOSE_DIR }
).toString();
check('DB rejects a second CONFIRMED row for a seat', dup.includes('Booking_seatId_confirmed_key'));

console.log(`\n${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
console.log(JSON.stringify({ eventId: event.id, s5: s5.id }));
process.exit(failures ? 1 : 0);

