import Redis, { Result } from 'ioredis';

// Each script runs atomically inside Redis, so no other command can land between its steps.
// KEYS[1] is the seat lock, KEYS[2] is the user's one-hold-per-event lock. Both hold the same token.

// 0 = held, 1 = seat already held by someone, 2 = this user already holds a seat for the event
const HOLD_SEAT = `
if redis.call('EXISTS', KEYS[2]) == 1 then return 2 end
if not redis.call('SET', KEYS[1], ARGV[1], 'NX', 'PXAT', ARGV[2]) then return 1 end
redis.call('SET', KEYS[2], ARGV[1], 'PXAT', ARGV[2])
return 0
`;

// Claims the hold for confirmation: if the token still owns the seat, the lock is kept for a
// short grace period while the database write happens. 1 = claimed, 0 = hold is gone.
const BEGIN_CONFIRM = `
if redis.call('GET', KEYS[1]) ~= ARGV[1] then return 0 end
redis.call('PEXPIRE', KEYS[1], ARGV[2])
if redis.call('GET', KEYS[2]) == ARGV[1] then redis.call('PEXPIRE', KEYS[2], ARGV[2]) end
return 1
`;

// Deletes the locks only if they still belong to this token, so a late call can never
// release a hold someone else has taken since.
const RELEASE_HOLD = `
local deleted = 0
for i = 1, 2 do
  if redis.call('GET', KEYS[i]) == ARGV[1] then deleted = deleted + redis.call('DEL', KEYS[i]) end
end
return deleted
`;

declare module 'ioredis' {
  interface RedisCommander<Context> {
    holdSeat(seatKey: string, userKey: string, token: string, expiresAtMs: number): Result<number, Context>;
    beginConfirm(seatKey: string, userKey: string, token: string, graceMs: number): Result<number, Context>;
    releaseHold(seatKey: string, userKey: string, token: string): Result<number, Context>;
  }
}

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379', {
  // Fail fast while Redis is unreachable instead of queueing commands, so a hold request
  // gets a 503 rather than hanging.
  enableOfflineQueue: false,
  maxRetriesPerRequest: 1,
});

redis.on('error', (err) => {
  console.error('Redis error:', err.message);
});

redis.defineCommand('holdSeat', { numberOfKeys: 2, lua: HOLD_SEAT });
redis.defineCommand('beginConfirm', { numberOfKeys: 2, lua: BEGIN_CONFIRM });
redis.defineCommand('releaseHold', { numberOfKeys: 2, lua: RELEASE_HOLD });

export default redis;

