import { randomUUID } from 'crypto';
import { Prisma } from '@prisma/client';
import prisma from '../db';
import redis from '../redis';
import { HttpError } from '../utils/http';

// Who holds a seat right now is decided by Redis: a lock key that expires on its own after the
// hold time. Postgres keeps the record of every hold (HELD, then CONFIRMED / EXPIRED / RELEASED)
// and is the final word on confirmed bookings through a unique index.

export const HOLD_MS = Number(process.env.HOLD_SECONDS || 600) * 1000;
// How long the seat lock survives once a confirm has started, so the database write can finish
// even if the confirm arrives in the hold's last second.
const CONFIRM_GRACE_MS = 30_000;
// The sweeper leaves rows alone for this long past expiry, so it never races a confirm in progress.
const SWEEP_GRACE_MS = 60_000;
const SWEEP_EVERY_MS = 30_000;

const HOLD_RESULT = { HELD: 0, SEAT_TAKEN: 1, ALREADY_HOLDING: 2 } as const;

// The {event:N} hash tag keeps all of one event's keys in the same slot if this ever moves to Redis Cluster.
function seatKey(eventId: number, seatId: number) {
  return `hold:{event:${eventId}}:seat:${seatId}`;
}

function userKey(eventId: number, userId: number) {
  return `hold:{event:${eventId}}:user:${userId}`;
}

async function withRedis<T>(command: () => Promise<T>): Promise<T> {
  try {
    return await command();
  } catch (err) {
    console.error('Redis command failed:', err);
    throw new HttpError(503, 'Seat holds are unavailable right now. Please try again shortly.');
  }
}

function isUniqueViolation(err: unknown) {
  return err instanceof Prisma.PrismaClientKnownRequestError && err.code === 'P2002';
}

export async function holdSeat(userId: number, seatId: number) {
  const seat = await prisma.seat.findUnique({ where: { id: seatId }, include: { event: true } });
  if (!seat) {
    throw new HttpError(404, 'Seat not found');
  }

  const now = Date.now();
  const startsAt = seat.event.startsAt.getTime();
  if (startsAt <= now) {
    throw new HttpError(400, 'This event has already started');
  }

  // A hold never outlives the event's start.
  const expiresAt = new Date(Math.min(now + HOLD_MS, startsAt));
  const token = randomUUID();
  const keys = [seatKey(seat.eventId, seatId), userKey(seat.eventId, userId)] as const;

  const result = await withRedis(() => redis.holdSeat(...keys, token, expiresAt.getTime()));
  if (result === HOLD_RESULT.ALREADY_HOLDING) {
    throw new HttpError(409, 'You already hold a seat for this event. Confirm or release it first.');
  }
  if (result === HOLD_RESULT.SEAT_TAKEN) {
    throw new HttpError(409, 'Someone else is holding this seat');
  }

  try {
    // Checked after taking the lock: a confirm writes CONFIRMED before it deletes its lock,
    // so once we hold the lock this read cannot miss a booking.
    const booked = await prisma.booking.findFirst({
      where: { seatId, status: 'CONFIRMED' },
      select: { id: true },
    });
    if (booked) {
      throw new HttpError(409, 'Seat already booked');
    }

    const hold = await prisma.booking.create({
      data: { seatId, userId, status: 'HELD', holdToken: token, expiresAt },
    });

    return { holdId: hold.id, seatId, label: seat.label, eventId: seat.eventId, expiresAt };
  } catch (err) {
    await redis.releaseHold(...keys, token).catch((releaseErr) => console.error('Hold cleanup failed:', releaseErr));
    throw err;
  }
}

export async function confirmHold(userId: number, holdId: number) {
  const hold = await prisma.booking.findFirst({
    where: { id: holdId, userId },
    include: { seat: true },
  });
  if (!hold) {
    throw new HttpError(404, 'Hold not found');
  }
  if (hold.status === 'CONFIRMED') {
    return hold;
  }
  if (hold.status !== 'HELD' || !hold.holdToken) {
    throw new HttpError(410, 'This hold has ended. The seat is back on sale.');
  }

  const token = hold.holdToken;
  const keys = [seatKey(hold.seat.eventId, hold.seatId), userKey(hold.seat.eventId, userId)] as const;

  const claimed = await withRedis(() => redis.beginConfirm(...keys, token, CONFIRM_GRACE_MS));
  if (!claimed) {
    await prisma.booking.updateMany({ where: { id: holdId, status: 'HELD' }, data: { status: 'EXPIRED' } });
    throw new HttpError(410, 'Your hold expired. The seat is back on sale.');
  }

  const releaseLocks = () =>
    redis.releaseHold(...keys, token).catch((err) => console.error('Releasing hold locks failed:', err));

  try {
    const updated = await prisma.booking.updateMany({
      where: { id: holdId, userId, status: 'HELD' },
      data: { status: 'CONFIRMED', confirmedAt: new Date() },
    });
    if (updated.count === 0) {
      throw new HttpError(410, 'This hold has ended. The seat is back on sale.');
    }
  } catch (err) {
    let failure = err;
    if (isUniqueViolation(err)) {
      await prisma.booking.update({ where: { id: holdId }, data: { status: 'RELEASED' } });
      failure = new HttpError(409, 'Seat already booked');
    }
    // A definite answer frees the locks now. Any other error keeps them for the grace period,
    // so a retry of the same confirm can still succeed.
    if (failure instanceof HttpError) {
      await releaseLocks();
    }
    throw failure;
  }

  await releaseLocks();

  return prisma.booking.findUniqueOrThrow({ where: { id: holdId } });
}

export async function releaseHold(userId: number, holdId: number) {
  const hold = await prisma.booking.findFirst({
    where: { id: holdId, userId, status: 'HELD' },
    include: { seat: true },
  });
  if (!hold || !hold.holdToken) {
    throw new HttpError(404, 'Hold not found');
  }

  const keys = [seatKey(hold.seat.eventId, hold.seatId), userKey(hold.seat.eventId, userId)] as const;
  await withRedis(() => redis.releaseHold(...keys, hold.holdToken!));
  await prisma.booking.updateMany({ where: { id: holdId, status: 'HELD' }, data: { status: 'RELEASED' } });
}

export async function getMyHolds(userId: number) {
  const holds = await prisma.booking.findMany({
    where: { userId, status: 'HELD', expiresAt: { gt: new Date() } },
    orderBy: { expiresAt: 'asc' },
    include: { seat: { include: { event: true } } },
  });

  return holds.map((h) => ({
    holdId: h.id,
    seatId: h.seatId,
    label: h.seat.label,
    expiresAt: h.expiresAt,
    event: {
      id: h.seat.event.id,
      title: h.seat.event.title,
      venue: h.seat.event.venue,
      startsAt: h.seat.event.startsAt,
    },
  }));
}

// The viewer's live hold on this event, if the Redis lock still backs it.
export async function getMyHoldForEvent(userId: number, eventId: number, heldTokens: Map<number, string>) {
  const hold = await prisma.booking.findFirst({
    where: { userId, status: 'HELD', expiresAt: { gt: new Date() }, seat: { eventId } },
    include: { seat: true },
  });
  if (!hold || heldTokens.get(hold.seatId) !== hold.holdToken) {
    return null;
  }
  return { holdId: hold.id, seatId: hold.seatId, label: hold.seat.label, expiresAt: hold.expiresAt };
}

// Seat id -> token of whoever holds it right now. Reads fail soft: if Redis is down the seat map
// still renders (from the database alone) and holding a seat returns 503.
export async function getHeldSeats(seats: { id: number; eventId: number }[]): Promise<Map<number, string>> {
  const held = new Map<number, string>();
  if (seats.length === 0) {
    return held;
  }

  try {
    const tokens = await redis.mget(seats.map((s) => seatKey(s.eventId, s.id)));
    tokens.forEach((token, i) => {
      if (token) held.set(seats[i].id, token);
    });
  } catch (err) {
    console.error('Reading seat holds failed:', err);
  }
