export function startHoldSweeper() {
  const timer = setInterval(() => {
    prisma.booking
      .updateMany({
        where: { status: 'HELD', expiresAt: { lt: new Date(Date.now() - SWEEP_GRACE_MS) } },
        data: { status: 'EXPIRED' },
      })
      .catch((err) => console.error('Hold sweep failed:', err));
  }, SWEEP_EVERY_MS);
  timer.unref();
}

import { Router } from 'express';
import { requireAuth, requireAttendee, AuthRequest } from '../middleware/auth';
import { confirmHold, getMyHolds, holdSeat, releaseHold } from '../services/holdService';
import { asyncHandler, parseId } from '../utils/http';

const router = Router();

router.post(
  '/',
  requireAuth,
  requireAttendee,
  asyncHandler(async (req: AuthRequest, res) => {
    const hold = await holdSeat(req.user!.id, parseId(req.body?.seatId, 'seatId'));
    res.status(201).json({ ...hold, serverTime: new Date() });
  })
);

router.get(
  '/mine',
  requireAuth,
  asyncHandler(async (req: AuthRequest, res) => {
    res.json({ holds: await getMyHolds(req.user!.id), serverTime: new Date() });
  })
);

router.post(
  '/:id/confirm',
  requireAuth,
  requireAttendee,
  asyncHandler(async (req: AuthRequest, res) => {
    const booking = await confirmHold(req.user!.id, parseId(req.params.id));
    res.json(booking);
  })
);

router.delete(
  '/:id',
  requireAuth,
  asyncHandler(async (req: AuthRequest, res) => {
    await releaseHold(req.user!.id, parseId(req.params.id));
    res.status(204).end();
  })
);

export default router;

