// End-to-end checks for seat holds against the running docker compose stack.
// Usage: node holds-e2e.mjs <compose dir> [compose project name]
import { execSync } from 'node:child_process';

const API = 'http://localhost:4000';
const COMPOSE_DIR = process.argv[2];
const COMPOSE = `docker compose${process.argv[3] ? ` -p ${process.argv[3]}` : ''}`;
let failures = 0;

function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
}

async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}

async function login(email) {
  const { data } = await call('POST', '/auth/login', null, { email, password: 'password123' });
  return data;
}

function sh(cmd) {
  return execSync(cmd, { cwd: COMPOSE_DIR }).toString().trim();
}
const redisCli = (args) => sh(`${COMPOSE} exec -T redis redis-cli ${args}`);
const seatStatus = async (eventId, seatId, token) =>
  (await call('GET', `/events/${eventId}`, token)).data.seats.find((s) => s.id === seatId).status;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const { token: alice, user: aliceUser } = await login('alice@seatbook.test');
const { token: bob, user: bobUser } = await login('bob@seatbook.test');
const { token: organizer } = await login('organizer@seatbook.test');

// Clear any live holds left by an earlier run.
for (const t of [alice, bob]) {
  const { data } = await call('GET', '/holds/mine', t);
  for (const h of data.holds) await call('DELETE', `/holds/${h.holdId}`, t);
}

const events = (await call('GET', '/events')).data;
