// End-to-end checks for seat holds against the running docker compose stack.
import { execSync } from 'node:child_process';

const API = 'http://localhost:4000';
const COMPOSE_DIR = process.argv[2];
let failures = 0;

function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
}

async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}

async function login(email) {
  const { data } = await call('POST', '/auth/login', null, { email, password: 'password123' });
  return data.token;
}

function redisCli(args) {
  return execSync(`docker compose -p seatbookclean exec -T redis redis-cli ${args}`, { cwd: COMPOSE_DIR }).toString().trim();
}

const alice = await login('alice@seatbook.test');
const bob = await login('bob@seatbook.test');
const organizer = await login('organizer@seatbook.test');

// Clear any live holds left by an earlier run.
for (const t of [alice, bob]) {
  const { data } = await call('GET', '/holds/mine', t);
  for (const h of data.holds) await call('DELETE', `/holds/${h.holdId}`, t);
}

const events = (await call('GET', '/events')).data;
const event = events.find((e) => new Date(e.startsAt) > new Date() && e.seatsLeft >= 6);
const detail = (await call('GET', `/events/${event.id}`)).data;
const free = detail.seats.filter((s) => s.status === 'available');
const [s1, s2, s3, s4, s5] = free;
console.log(`Using event ${event.id} "${event.title}", seats ${[s1, s2, s3, s4, s5].map((s) => s.label).join(', ')}\n`);

// 1. Race: 20 parallel holds on one seat from two users.
const race = await Promise.all(
  Array.from({ length: 20 }, (_, i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s1.id }))
);
const winners = race.filter((r) => r.status === 201);
check('20 parallel holds on one seat -> exactly one wins', winners.length === 1, `201s=${winners.length}, others=${[...new Set(race.filter((r) => r.status !== 201).map((r) => r.status))]}`);
const winnerToken = winners[0].data && race.indexOf(winners[0]) % 2 ? bob : alice;
const loserToken = winnerToken === alice ? bob : alice;
const hold1 = winners[0].data;
check('hold expires about 10 minutes out', Math.abs(new Date(hold1.expiresAt) - new Date(hold1.serverTime) - 600000) < 2000);

// 2. One hold per user per event.
const second = await call('POST', '/holds', winnerToken, { seatId: s2.id });
check('second hold by same user on same event -> 409', second.status === 409, second.data.error);

