check('confirm own hold -> CONFIRMED', confirmed.status === 200 && confirmed.data.status === 'CONFIRMED');
const again = await call('POST', `/holds/${hold1.holdId}/confirm`, winnerToken);
check('confirm twice is harmless', again.status === 200 && again.data.status === 'CONFIRMED');
check('redis locks removed after confirm', redisCli(`--scan --pattern 'hold:{event:${event.id}}:*'`) === '');
const afterConfirm = (await call('GET', `/events/${event.id}`)).data;
