// Re-checks finding 1 (double booking) and checks finding 2 (cancel ownership) against the running stack.
const API = 'http://localhost:4000';
let failures = 0;

function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
}

async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}

const login = async (email) => (await call('POST', '/auth/login', null, { email, password: 'password123' })).data.token;
const alice = await login('alice@seatbook.test');
const bob = await login('bob@seatbook.test');
const myBooking = async (token, id) => (await call('GET', '/bookings/mine', token)).data.find((b) => b.id === id);
const seatStatus = async (eventId, seatId) =>
  (await call('GET', `/events/${eventId}`)).data.seats.find((s) => s.id === seatId).status;

for (const t of [alice, bob]) {
  for (const h of (await call('GET', '/holds/mine', t)).data.holds) await call('DELETE', `/holds/${h.holdId}`, t);
}

const event = (await call('GET', '/events')).data.find((e) => new Date(e.startsAt) > new Date() && e.seatsLeft >= 4);
const free = (await call('GET', `/events/${event.id}`)).data.seats.filter((s) => s.status === 'available');
const [s1, s2, s3] = free;
console.log(`Using event ${event.id} "${event.title}", seats ${s1.label}, ${s2.label}, ${s3.label}\n`);

console.log('-- Finding 1: double booking');
const holdRace = await Promise.all(Array.from({ length: 30 }, (_, i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s1.id })));
const holdWinners = holdRace.filter((r) => r.status === 201);
check('30 parallel holds on one seat -> exactly one wins', holdWinners.length === 1, `201s=${holdWinners.length}`);
const winnerToken = holdRace.indexOf(holdWinners[0]) % 2 ? bob : alice;
await call('DELETE', `/holds/${holdWinners[0].data.holdId}`, winnerToken);

const bookRace = await Promise.all(Array.from({ length: 30 }, (_, i) => call('POST', '/bookings', i % 2 ? bob : alice, { seatId: s2.id })));
const bookWinners = bookRace.filter((r) => r.status === 201);
check('30 parallel direct bookings on one seat -> exactly one wins', bookWinners.length === 1, `201s=${bookWinners.length}`);
check('the losers got 409, not 500', bookRace.filter((r) => r.status !== 201).every((r) => r.status === 409));

console.log('\n-- Finding 2: cancel');
const booked = (await call('POST', '/bookings', alice, { seatId: s3.id })).data;
check('alice books a seat', booked.status === 'CONFIRMED');

const bobCancels = await call('POST', `/bookings/${booked.id}/cancel`, bob);
check("bob cancelling alice's booking -> 404", bobCancels.status === 404, bobCancels.data.error);
check("alice's booking is still CONFIRMED", (await myBooking(alice, booked.id)).status === 'CONFIRMED');
check('seat is still booked', (await seatStatus(event.id, s3.id)) === 'booked');

check('logged out cancel -> 401', (await call('POST', `/bookings/${booked.id}/cancel`, null)).status === 401);
check('cancel /bookings/abc -> 400', (await call('POST', '/bookings/abc/cancel', alice)).status === 400);
check('cancel a missing booking -> 404', (await call('POST', '/bookings/99999999/cancel', alice)).status === 404);

const hold = (await call('POST', '/holds', alice, { seatId: free[3].id })).data;
check('cancel on a hold id -> 404 (holds use DELETE /holds/:id)', (await call('POST', `/bookings/${hold.holdId}/cancel`, alice)).status === 404);
await call('DELETE', `/holds/${hold.holdId}`, alice);

const own = await call('POST', `/bookings/${booked.id}/cancel`, alice);
check('alice cancels her own booking -> 200 CANCELLED', own.status === 200 && own.data.status === 'CANCELLED' && own.data.cancelledAt, JSON.stringify(own.data));
const again = await call('POST', `/bookings/${booked.id}/cancel`, alice);
check('cancelling again -> 200, same cancelledAt', again.status === 200 && again.data.cancelledAt === own.data.cancelledAt);
check('My Bookings shows CANCELLED', (await myBooking(alice, booked.id)).status === 'CANCELLED');
check('seat is free again', (await seatStatus(event.id, s3.id)) === 'available');
const rebook = await call('POST', '/bookings', bob, { seatId: s3.id });
check('someone else can book the freed seat', rebook.status === 201);

const parallel = await Promise.all(Array.from({ length: 10 }, () => call('POST', `/bookings/${rebook.data.id}/cancel`, bob)));
check('10 parallel cancels by the owner all -> 200', parallel.every((r) => r.status === 200));
check('...and agree on one cancelledAt', new Set(parallel.map((r) => r.data.cancelledAt)).size === 1);

const past = (await call('GET', '/bookings/mine', alice)).data.find(
  (b) => b.status === 'CONFIRMED' && new Date(b.event.startsAt) < new Date()
);
if (past) {
  const pastCancel = await call('POST', `/bookings/${past.id}/cancel`, alice);
  check('cancelling a booking for an event that already started -> 400', pastCancel.status === 400, pastCancel.data.error);
  check('...and it stays CONFIRMED', (await myBooking(alice, past.id)).status === 'CONFIRMED');
} else {
  check('found a past confirmed booking to test with', false);
}

check('server still up', (await call('GET', '/health')).status === 200);

console.log(`\n${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
process.exit(failures ? 1 : 0);

