// Checks POST /events validation, the price in particular, against the running stack.
const API = 'http://localhost:4000';
const TITLE = 'E2E price check';
let failures = 0;

function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
}

async function call(method, path, token, body, raw) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: raw ?? (body ? JSON.stringify(body) : undefined),
  });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}

const login = async (email) => (await call('POST', '/auth/login', null, { email, password: 'password123' })).data.token;
const organizer = await login('organizer@seatbook.test');
const alice = await login('alice@seatbook.test');

const inAWeek = new Date(Date.now() + 7 * 86400000).toISOString();
const valid = { title: TITLE, description: 'test', venue: 'Test Hall', startsAt: inAWeek, rows: 2, cols: 3, priceCents: 1500 };

console.log('-- price');
for (const [name, priceCents] of [
  ['negative', -500],
  ['fractional cents', 1500.5],
  ['a string', '1500'],
  ['null (what NaN becomes in JSON)', null],
  ['over $10,000', 1_000_001],
  ['an object', { amount: 1500 }],
]) {
  const r = await call('POST', '/events', organizer, { ...valid, priceCents });
  check(`price ${name} -> 400`, r.status === 400, r.data.error);
}

const created = await call('POST', '/events', organizer, valid);
check('valid event -> 201 with priceCents 1500', created.status === 201 && created.data.priceCents === 1500);
const detail = await call('GET', `/events/${created.data.id}`);
check('event page shows $15.00 from the database', detail.data.price === '$15.00' && detail.data.seats.length === 6);

const { priceCents: _, ...noPrice } = valid;
const free = await call('POST', '/events', organizer, noPrice);
check('price left out -> free event', free.status === 201 && free.data.priceCents === 0);

console.log('\n-- other fields');
for (const [name, patch] of [
  ['rows 0', { rows: 0 }],
  ['rows 27', { rows: 27 }],
  ['rows "5"', { rows: '5' }],
  ['cols 31', { cols: 31 }],
  ['negative cols', { cols: -2 }],
  ['blank title', { title: '  ' }],
  ['missing venue', { venue: undefined }],
  ['invalid date', { startsAt: 'tomorrow' }],
  ['date in the past', { startsAt: '2020-01-01T00:00:00Z' }],
]) {
  const r = await call('POST', '/events', organizer, { ...valid, ...patch });
  check(`${name} -> 400`, r.status === 400, r.data.error);
}
check('empty body -> 400', (await call('POST', '/events', organizer, {})).status === 400);
check('broken JSON -> 400', (await call('POST', '/events', organizer, null, '{"title":')).status === 400);

console.log('\n-- who may create');
check('attendee -> 403', (await call('POST', '/events', alice, valid)).status === 403);
check('logged out -> 401', (await call('POST', '/events', null, valid)).status === 401);

console.log('\n-- booking uses the database price');
const seatId = detail.data.seats[0].id;
const booked = await call('POST', '/bookings', alice, { seatId, priceCents: 1 });
const mine = (await call('GET', '/bookings/mine', alice)).data.find((b) => b.id === booked.data.id);
check('a price sent with a booking is ignored; My Bookings shows $15.00', booked.status === 201 && mine?.event.price === '$15.00', mine?.event.price);

check('server still up', (await call('GET', '/health')).status === 200);

console.log(`\n${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
process.exit(failures ? 1 : 0);

