// Checks that sign-up can only create attendees. Test users use the e2e-signup- email prefix.
const API = 'http://localhost:4000';
let failures = 0;
const check = (name, ok, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
};
async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data; try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}
const run = Date.now();
const signup = (tag, extra) =>
  call('POST', '/auth/register', null, { email: `e2e-signup-${tag}-${run}@seatbook.test`, password: 'test-password-1', name: 'E2E', ...extra });
const login = (tag) => call('POST', '/auth/login', null, { email: `e2e-signup-${tag}-${run}@seatbook.test`, password: 'test-password-1' });

for (const [name, role] of [['ORGANIZER', 'ORGANIZER'], ['lowercase organizer', 'organizer'], ['an array', ['ORGANIZER']], ['an object', { role: 'ORGANIZER' }], ['null', null], ['ADMIN', 'ADMIN']]) {
  const r = await signup(`bad${name.replace(/\W/g, '')}`, { role });
  check(`sign-up with role ${name} -> 403`, r.status === 403, r.data.error);
  const l = await login(`bad${name.replace(/\W/g, '')}`);
  check('  ...and no account was created', l.status === 401);
}

const plain = await signup('plain');
check('sign-up without a role -> 201 ATTENDEE', plain.status === 201 && plain.data.user.role === 'ATTENDEE');
const explicit = await signup('attendee', { role: 'ATTENDEE' });
check('sign-up with role ATTENDEE -> 201 ATTENDEE', explicit.status === 201 && explicit.data.user.role === 'ATTENDEE');

const create = await call('POST', '/events', plain.data.token, { title: 'x', venue: 'y', startsAt: new Date(Date.now() + 864e5).toISOString(), rows: 1, cols: 1 });
check('a signed-up account cannot create events -> 403', create.status === 403);

const org = await call('POST', '/auth/login', null, { email: 'organizer@seatbook.test', password: 'password123' });
check('seeded organizer still logs in as ORGANIZER', org.status === 200 && org.data.user.role === 'ORGANIZER');
const orgCheck = await call('POST', '/events', org.data.token, {});
check('seeded organizer still passes the organizer check (gets 400 for the empty body, not 403)', orgCheck.status === 400);

console.log(`\n${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
process.exit(failures ? 1 : 0);
EOF
