import jwt from 'jsonwebtoken';

const JWT_SECRET = process.env.JWT_SECRET || 'seatbook-secret-123';

export interface AuthUser {
  id: number;
  email: string;
  role: 'ORGANIZER' | 'ATTENDEE';
