import { describe, it, expect } from 'vitest';
import { readdirSync, readFileSync } from 'fs';
import { join } from 'path';

// Express 4 does not catch a rejected promise from an async handler, and an unhandled rejection
// used to take the whole server down. Every async handler in a router must go through asyncHandler,
// which hands its errors to the error middleware. This fails if one is added without it.
const routesDir = join(__dirname, '../src/routes');

describe('route handlers', () => {
  const files = readdirSync(routesDir).filter((f) => f.endsWith('.ts'));

  it('finds the route files', () => {
    expect(files).toEqual(expect.arrayContaining(['auth.ts', 'bookings.ts', 'events.ts', 'holds.ts']));
  });

  it.each(files)('%s wraps every async handler in asyncHandler', (file) => {
    const source = readFileSync(join(routesDir, file), 'utf8');
    const asyncHandlers = source.match(/async \(/g) ?? [];
    const wrapped = source.match(/asyncHandler\(async \(/g) ?? [];
    expect(asyncHandlers.length).toBeGreaterThan(0);
    expect(wrapped.length).toBe(asyncHandlers.length);
  });
});

// Throws bad input at every route. After each request the server must still be up, the answer must
// be a 4xx with a JSON { error }, and nothing from Prisma may leak into the response.
const API = 'http://localhost:4000';
let failures = 0;
let sent = 0;

async function raw(method, path, { token, body, contentType = 'application/json' } = {}) {
  const res = await fetch(API + path, {
    method,
    headers: { ...(contentType ? { 'Content-Type': contentType } : {}), ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body,
  });
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch {}
  return { status: res.status, text, json };
}

async function alive() {
  try { return (await fetch(API + '/health')).status === 200; } catch { return false; }
}

async function probe(label, method, path, opts) {
  sent++;
  let r;
  try {
    r = await raw(method, path, opts);
  } catch (err) {
    console.log(`FAIL  ${label}: request failed (${err.cause?.code ?? err.message})`);
    failures++;
    return;
  }
  const problems = [];
  if (r.status >= 500) problems.push(`status ${r.status}`);
  if (!r.json || typeof r.json.error !== 'string') problems.push(`no JSON error body: ${r.text.slice(0, 80)}`);
  if (/prisma|invocation|stack|at \w+ \(/i.test(r.text)) problems.push(`leaks internals: ${r.text.slice(0, 120)}`);
  if (!(await alive())) problems.push('SERVER DOWN afterwards');
  if (problems.length) {
    console.log(`FAIL  ${label} -> ${r.status}: ${problems.join('; ')}`);
    failures++;
  }
}

const login = async (email) => (await raw('POST', '/auth/login', { body: JSON.stringify({ email, password: 'password123' }) })).json.token;
const alice = await login('alice@seatbook.test');
const organizer = await login('organizer@seatbook.test');

// Bodies that are wrong as a whole.
const badBodies = {
  'no body': { body: undefined },
  'empty object': { body: '{}' },
  'JSON null': { body: 'null' },
  'JSON array': { body: '[]' },
  'JSON string': { body: '"hello"' },
  'JSON number': { body: '42' },
  'broken JSON': { body: '{"email":' },
  'not JSON content type': { body: 'email=a&password=b', contentType: 'application/x-www-form-urlencoded' },
  'text/plain': { body: 'hello', contentType: 'text/plain' },
  'body over 100kb limit': { body: JSON.stringify({ email: 'x'.repeat(200_000) }) },
};

// Field values of the wrong type or shape.
const badValues = [null, 123, true, [], ['a'], { $gt: '' }, '', ' ', 'x'.repeat(5000), -1, 0, 1.5, 1e20, 'NaN', '1; DROP TABLE "User"'];

// Ids that are not real ids.
const badIds = ['abc', '-1', '0', '1.5', '1e3', '99999999999999999999', '2147483648', '%00', 'null', ' ', '1abc', 'x'.repeat(500)];

const routes = [
  { method: 'POST', path: '/auth/login', fields: ['email', 'password'] },
  { method: 'POST', path: '/auth/register', fields: ['email', 'password', 'name', 'role'] },
  { method: 'POST', path: '/events', token: organizer, fields: ['title', 'venue', 'startsAt', 'rows', 'cols', 'priceCents', 'description'] },
  { method: 'POST', path: '/holds', token: alice, fields: ['seatId'] },
  { method: 'POST', path: '/holds/confirm', token: alice, fields: ['eventId'] },
  { method: 'POST', path: '/bookings', token: alice, fields: ['seatId'] },
];

console.log('-- whole-body garbage on every POST route');
for (const route of routes) {
  for (const [name, opts] of Object.entries(badBodies)) {
    await probe(`${route.method} ${route.path} with ${name}`, route.method, route.path, { token: route.token, ...opts });
  }
}

console.log('-- wrong field types on every POST route');
const validRegister = { email: 'fuzz@seatbook.test', password: 'long-enough-1', name: 'Fuzz' };
for (const route of routes) {
  for (const field of route.fields) {
    for (const value of badValues) {
      const base = route.path === '/auth/register' ? { ...validRegister } : route.path === '/auth/login' ? { email: 'alice@seatbook.test', password: 'password123' } : {};
      const body = JSON.stringify({ ...base, [field]: value });
      await probe(`${route.method} ${route.path} ${field}=${JSON.stringify(value).slice(0, 30)}`, route.method, route.path, { token: route.token, body });
    }
  }
}

console.log('-- bad ids in every :id route');
for (const id of badIds) {
  const enc = encodeURIComponent(id);
  await probe(`GET /events/${id.slice(0, 20)}`, 'GET', `/events/${enc}`);
  await probe(`POST /bookings/${id.slice(0, 20)}/cancel`, 'POST', `/bookings/${enc}/cancel`, { token: alice });
  await probe(`DELETE /holds/${id.slice(0, 20)}`, 'DELETE', `/holds/${enc}`, { token: alice });
}

console.log('-- auth header garbage');
for (const header of ['Bearer', 'Bearer ', 'Bearer x.y.z', 'Basic abc', 'Bearer ' + 'a'.repeat(10_000), 'null']) {
  const res = await fetch(API + '/bookings/mine', { headers: { Authorization: header } });
  sent++;
  if (res.status !== 401 || !(await alive())) { console.log(`FAIL  Authorization "${header.slice(0, 20)}" -> ${res.status}`); failures++; }
}

console.log('-- unknown routes');
await probe('GET /nope', 'GET', '/nope');
await probe('POST /events/1/whatever', 'POST', '/events/1/whatever');

// The original crash cases, called out by name.
console.log('-- the three crashes from the review');
for (const [label, method, path, token] of [
  ['POST /auth/login with no body', 'POST', '/auth/login'],
  ['GET /events/abc', 'GET', '/events/abc'],
  ['POST /bookings/abc/cancel', 'POST', '/bookings/abc/cancel', alice],
]) {
  const r = await raw(method, path, { token, contentType: null });
  const up = await alive();
  console.log(`${r.status < 500 && up ? 'PASS' : 'FAIL'}  ${label} -> ${r.status} ${r.text}${up ? '' : '  SERVER DOWN'}`);
  if (!(r.status < 500 && up)) failures++;
}

console.log(`\n${sent} bad requests sent. ${failures === 0 ? 'Server stayed up, no 500s, no leaks.' : `${failures} problem(s).`}`);
process.exit(failures ? 1 : 0);

