// Key checks for review findings 1-4, re-run after the finding 5 changes.
const API = 'http://localhost:4000';
let failures = 0;
const check = (name, ok, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
};
async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data; try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}
const login = async (email) => (await call('POST', '/auth/login', null, { email, password: 'password123' })).data.token;
const alice = await login('alice@seatbook.test');
const bob = await login('bob@seatbook.test');
const organizer = await login('organizer@seatbook.test');
check('seeded accounts log in', !!alice && !!bob && !!organizer);

for (const t of [alice, bob]) for (const h of (await call('GET', '/holds/mine', t)).data.holds) await call('DELETE', `/holds/${h.holdId}`, t);
const event = (await call('GET', '/events')).data.find((e) => new Date(e.startsAt) > new Date() && e.seatsLeft >= 3);
const [s1, s2, s3] = (await call('GET', `/events/${event.id}`)).data.seats.filter((s) => s.status === 'available');

console.log('-- 1 double booking');
const race = await Promise.all(Array.from({ length: 30 }, (_, i) => call('POST', '/bookings', i % 2 ? bob : alice, { seatId: s1.id })));
check('30 parallel bookings on one seat -> exactly one 201, rest 409', race.filter((r) => r.status === 201).length === 1 && race.every((r) => [201, 409].includes(r.status)));
const holdRace = await Promise.all(Array.from({ length: 30 }, (_, i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s2.id })));
const winner = holdRace.find((r) => r.status === 201);
check('30 parallel holds on one seat -> exactly one wins', holdRace.filter((r) => r.status === 201).length === 1);
await call('DELETE', `/holds/${winner.data.holdId}`, holdRace.indexOf(winner) % 2 ? bob : alice);

console.log('-- 2 cancel');
const booked = (await call('POST', '/bookings', alice, { seatId: s3.id })).data;
check("bob cancelling alice's booking -> 404", (await call('POST', `/bookings/${booked.id}/cancel`, bob)).status === 404);
const own = await call('POST', `/bookings/${booked.id}/cancel`, alice);
check('alice cancels her own -> 200 CANCELLED', own.status === 200 && own.data.status === 'CANCELLED');
check('cancelling again -> 200', (await call('POST', `/bookings/${booked.id}/cancel`, alice)).status === 200);

console.log('-- 3 organizer sign-up');
const tag = Date.now();
const reg = (role) => call('POST', '/auth/register', null, { email: `e2e-reg-${role ?? 'none'}-${tag}@seatbook.test`, password: 'test-password-1', name: 'E2E', ...(role ? { role } : {}) });
check('sign-up as ORGANIZER -> 403', (await reg('ORGANIZER')).status === 403);
const plain = await reg();
check('plain sign-up -> 201 ATTENDEE', plain.status === 201 && plain.data.user.role === 'ATTENDEE');
check('duplicate email -> 409', (await call('POST', '/auth/register', null, { email: `e2e-reg-none-${tag}@seatbook.test`, password: 'test-password-1', name: 'E2E' })).status === 409);
check('short password -> 400', (await call('POST', '/auth/register', null, { email: `e2e-reg-short-${tag}@seatbook.test`, password: 'short', name: 'E2E' })).status === 400);
check('wrong password -> 401', (await call('POST', '/auth/login', null, { email: 'alice@seatbook.test', password: 'nope-nope' })).status === 401);

console.log('-- price validation');
const ev = { title: 'E2E price check', venue: 'Hall', startsAt: new Date(Date.now() + 864e5).toISOString(), rows: 1, cols: 1 };
check('negative price -> 400', (await call('POST', '/events', organizer, { ...ev, priceCents: -1 })).status === 400);
check('null price -> 400', (await call('POST', '/events', organizer, { ...ev, priceCents: null })).status === 400);
check('valid event -> 201', (await call('POST', '/events', organizer, { ...ev, priceCents: 1500 })).status === 201);

console.log('-- 4 jwt');
check('token from login works', (await call('GET', '/bookings/mine', alice)).status === 200);
check('garbage token -> 401', (await call('GET', '/bookings/mine', 'x.y.z')).status === 401);

console.log(`\n${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
process.exit(failures ? 1 : 0);

