input.content:
// Turns a Claude Code transcript.jsonl into a readable Markdown conversation:
// user messages, assistant replies, and a one-line note per tool call. Tool output is left out.
// Usage: node to-markdown.mjs <transcript.jsonl> <out.md>
import { readFileSync, writeFileSync } from 'node:fs';

const [input, output] = process.argv.slice(2);
const records = readFileSync(input, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));

const seen = new Set();
const out = ['# Claude Code session: Seatbook take-home', ''];
let turns = 0;

function toolNote(block) {
  const i = block.input ?? {};
  const name = block.name.replace(/^mcp__[^_]+(__[^_]+)?__/, '');
  const detail = i.description || i.file_path || i.query || i.url || i.action || (i.items ? 'task list' : '') || '';
  return `- _${name}_${detail ? `: ${String(detail).replace(/\s+/g, ' ').slice(0, 140)}` : ''}`;
}

for (const r of records) {
  if (r.uuid && seen.has(r.uuid)) continue;
  if (r.uuid) seen.add(r.uuid);

  if (r.type === 'user' && !r.isMeta) {
    const content = r.message?.content;
    const parts = typeof content === 'string' ? [content] : (content ?? []).filter((c) => c.type === 'text').map((c) => c.text);
    const text = parts
      .map((t) => t.replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '').trim())
      .filter((t) => t && !t.startsWith('<command-') && !t.startsWith('Base directory for this skill'))
      .join('\n\n');
    if (!text) continue;
    turns++;
    out.push('---', '', `## User (${turns})`, '', text, '');
  }

  if (r.type === 'assistant') {
    for (const block of r.message?.content ?? []) {
      if (block.type === 'text' && block.text.trim()) out.push('### Claude', '', block.text.trim(), '');
      if (block.type === 'tool_use') out.push(toolNote(block));
    }
    out.push('');
  }
}

writeFileSync(output, out.join('\n').replace(/\n{3,}/g, '\n\n'));
console.log(`${turns} user turns written to ${output}`);

