        <div className="text-white/50 text-sm">
          📍 {hold.event.venue} · 💺 {hold.label}
        </div>
      </div>
      <div className="flex items-center gap-6">
        {msLeft > 0 ? (
          <>
            <span className="text-2xl font-extrabold tabular-nums text-[#fdba74]">⏳ {formatCountdown(msLeft)}</span>
            <Link
              to={`/events/${hold.event.id}`}
              className="px-4 py-2 rounded-xl bg-gradient-to-r from-[#a855f7] to-[#ec4899] text-sm font-semibold hover:scale-105 transition-all duration-300"
            >
              Confirm →
            </Link>
          </>
        ) : (
          <span className="text-white/40">⌛ Hold expired</span>
        )}
      </div>
    </div>
  );
}

export default function MyBookingsPage() {
  const [holds, setHolds] = useState<Hold[]>([]);
  const [clockOffset, setClockOffset] = useState(0);
  const [bookings, setBookings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [totalSpent, setTotalSpent] = useState(0);
  const [upcoming, setUpcoming] = useState(0);
  const [toast, setToast] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const [cancelTarget, setCancelTarget] = useState<any>(null);
  const [cancelling, setCancelling] = useState(false);

  const loadBookings = () => {
    apiFetch(`${API_URL}/bookings/mine`, {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
    })
      .then((res) => {
        if (!res.ok) throw new Error(`GET /bookings/mine failed: ${res.status}`);
        return res.json();
      })
      .then((data) => {
        setBookings(data);

        let spent = 0;
        let up = 0;
        data.forEach((b: any) => {
          if (b.status === 'CONFIRMED') spent += parseFloat(b.event.price.replace('$', ''));
          if (new Date(b.event.startsAt) > new Date()) up++;
        });
        setTotalSpent(spent);
        setUpcoming(up);
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setError("Couldn't load your bookings 😢");
        setLoading(false);
      });
  };

  const loadHolds = () => {
    apiFetch(`${API_URL}/holds/mine`, {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
    })
      .then((res) => {
        if (!res.ok) throw new Error();
        return res.json();
      })
      .then((data) => {
        setClockOffset(new Date(data.serverTime).getTime() - Date.now());
        setHolds(data.holds);
      })
      .catch((err) => {
        console.error(err);
        setError("Couldn't load your seats on hold 😢");
      });
  };

  useEffect(() => {
    loadBookings();
    loadHolds();
  }, []);

  const showToast = (type: 'success' | 'error', message: string) => {
    setToast({ type, message });
    setTimeout(() => setToast(null), 3000);
  };

