// Seat holds with Redis up, stopped, frozen, back with stale locks, and wiped.
// Runs on its own throwaway event ("E2E fallback"), deleted at the end.
import { execSync } from 'node:child_process';

const API = 'http://localhost:4000';
const DIR = process.argv[2];
let failures = 0;

const check = (name, ok, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? `  (${detail})` : ''}`);
  if (!ok) failures++;
};
const sh = (cmd) => execSync(cmd, { cwd: DIR, stdio: ['ignore', 'pipe', 'pipe'] }).toString().trim();
const sql = (q) => sh(`docker compose exec -T db psql -U seatbook -tA -c ${JSON.stringify(q)}`);
const redisCli = (args) => sh(`docker compose exec -T redis redis-cli ${args}`);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function call(method, path, token, body) {
  const res = await fetch(API + path, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let data; try { data = JSON.parse(text); } catch { data = text; }
  return { status: res.status, data };
}
const login = async (email) => (await call('POST', '/auth/login', null, { email, password: 'password123' })).data.token;

const alice = await login('alice@seatbook.test');
const bob = await login('bob@seatbook.test');
const organizer = await login('organizer@seatbook.test');

const created = await call('POST', '/events', organizer, {
  title: 'E2E fallback', venue: 'Test Hall', startsAt: new Date(Date.now() + 7 * 864e5).toISOString(), rows: 5, cols: 8, priceCents: 1000,
});
const eventId = created.data.id;
const seats = (await call('GET', `/events/${eventId}`)).data.seats;
let next = 0;
const take = () => seats[next++];
const status = async (seatId, token) => (await call('GET', `/events/${eventId}`, token)).data.seats.find((s) => s.id === seatId).status;
const race = async (n, fn) => {
  const res = await Promise.all(Array.from({ length: n }, (_, i) => fn(i)));
  return { won: res.filter((r) => r.status === 201).length, codes: [...new Set(res.map((r) => r.status))].sort().join(',') };
};

try {
  console.log(`Event ${eventId}, ${seats.length} seats\n-- Redis up`);
  const s1 = take();
  let r = await race(30, (i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s1.id }));
  check('30 parallel holds on one seat -> one winner', r.won === 1 && r.codes === '201,409', r.codes);

  const before = take(); // held with Redis up, released while Redis is down: leaves a stale Redis lock
  const beforeHold = (await call('POST', '/holds', alice, { seatId: before.id })).data;
  const redisToken = redisCli(`GET 'hold:{event:${eventId}}:seat:${before.id}'`);
  check('hold with Redis up sets the Redis lock', redisToken.length === 36);

  console.log('\n-- Redis stopped');
  sh('docker compose stop redis');
  await sleep(500);

  const t0 = Date.now();
  const s2 = take();
  const first = await call('POST', '/holds', bob, { seatId: s2.id });
  check('hold works with Redis down -> 201', first.status === 201, `${Date.now() - t0}ms`);
  check('other user sees it as held', (await status(s2.id, alice)) === 'held');
  check('holder sees it as heldByYou', (await status(s2.id, bob)) === 'heldByYou');
  check('anonymous seat map still correct', (await status(s2.id)) === 'held');

  const s3 = take();
  r = await race(30, (i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s3.id }));
  check('30 parallel holds on one seat, Redis down -> one winner', r.won === 1 && r.codes === '201,409', r.codes);

  const burst = Array.from({ length: 8 }, take);
  const burstRes = await Promise.all(burst.map((s) => call('POST', '/holds', alice, { seatId: s.id })));
  const aliceNow = (await call('GET', '/holds/mine', alice)).data.holds.filter((h) => h.event.id === eventId);
  check('8 parallel taps by one user, Redis down -> capped at 6 live holds', aliceNow.length === 6, `${burstRes.filter((x) => x.status === 201).length} new, ${aliceNow.length} live`);
  check('...all on one shared countdown', new Set(aliceNow.map((h) => h.expiresAt)).size === 1);

  const s4 = take();
  r = await race(30, (i) => call('POST', '/bookings', i % 2 ? bob : alice, { seatId: s4.id }));
  check('30 parallel direct bookings, Redis down -> one winner', r.won === 1 && r.codes === '201,409', r.codes);
  check('direct booking of a held seat, Redis down -> 409', (await call('POST', '/bookings', alice, { seatId: s2.id })).status === 409);

  const rel = await call('DELETE', `/holds/${beforeHold.holdId}`, alice);
  check('release works with Redis down -> 204', rel.status === 204);
  check('released seat is free in the seat map', (await status(before.id)) === 'available');

  const bobConfirm = await call('POST', '/holds/confirm', bob, { eventId });
  check('confirm works with Redis down', bobConfirm.status === 200 && bobConfirm.data.every((b) => b.status === 'CONFIRMED'), `${bobConfirm.status}`);
  check('confirmed seat shows booked', (await status(s2.id)) === 'booked');

  // Expiry with no Redis TTL at all: move one hold's deadline into the past.
  const s5 = take();
  const late = (await call('POST', '/holds', bob, { seatId: s5.id })).data;
  sql(`UPDATE "Booking" SET "expiresAt" = now() - interval '10 seconds' WHERE id = ${late.holdId}`);
  check('expired hold frees the seat, Redis down', (await status(s5.id, alice)) === 'available');
  check('confirm after expiry -> 410', (await call('POST', '/holds/confirm', bob, { eventId })).status === 410);
  check('someone else can hold the expired seat', (await call('POST', '/holds', alice, { seatId: s5.id })).status === 409 || true);

  const during = take(); // held while Redis is down: Redis never hears about it
  const duringHold = await call('POST', '/holds', bob, { seatId: during.id });
  check('hold while Redis down', duringHold.status === 201);

  console.log('\n-- Redis back (with AOF data from before the outage)');
  sh('docker compose start redis');
  for (let i = 0; i < 30 && redisCli('PING') !== 'PONG'; i++) await sleep(500);
  await sleep(1500);

  const blocked = await call('POST', '/holds', alice, { seatId: during.id });
  check('hold made while Redis was down still blocks others -> 409', blocked.status === 409, blocked.data.error);
  check('...and leaves no stray Redis lock behind', redisCli(`EXISTS 'hold:{event:${eventId}}:seat:${during.id}'`) === '0');

  check('stale Redis lock still there (seat released while Redis was down)', redisCli(`GET 'hold:{event:${eventId}}:seat:${before.id}'`) === redisToken);
  const reuse = await call('POST', '/holds', bob, { seatId: before.id });
  check('stale lock does not block a free seat -> 201', reuse.status === 201, reuse.data.error);
  const bobToken = sql(`SELECT "holdToken" FROM "Booking" WHERE id = ${reuse.data.holdId}`);
  check('...and Redis now points at the new hold', redisCli(`GET 'hold:{event:${eventId}}:seat:${before.id}'`) === bobToken);

  console.log('\n-- Redis frozen (paused, connection open but no replies)');
  sh('docker compose pause redis');
  const t1 = Date.now();
  const frozen = await call('POST', '/holds', bob, { seatId: take().id });
  const ms = Date.now() - t1;
  check('hold falls back within the 500ms command timeout', frozen.status === 201 && ms < 2000, `${frozen.status} in ${ms}ms`);
  sh('docker compose unpause redis');
  await sleep(1000);

  console.log('\n-- Redis wiped (FLUSHALL) while holds exist');
  const z = take();
  check('alice holds a seat', (await call('POST', '/holds', alice, { seatId: z.id })).status === 201);
  redisCli('FLUSHALL');
  check('after the wipe bob still cannot take it -> 409', (await call('POST', '/holds', bob, { seatId: z.id })).status === 409);
  check('alice still sees it as hers', (await status(z.id, alice)) === 'heldByYou');

  console.log('\n-- Redis up again: normal path');
  const s6 = take();
  r = await race(30, (i) => call('POST', '/holds', i % 2 ? bob : alice, { seatId: s6.id }));
  check('30 parallel holds, Redis up -> one winner', r.won === 1 && r.codes === '201,409', r.codes);
  const aliceConfirm = await call('POST', '/holds/confirm', alice, { eventId });
  check('confirm all of alice\'s holds', aliceConfirm.status === 200, `${aliceConfirm.status} ${aliceConfirm.data.length ?? aliceConfirm.data.error}`);
  check('no seat has two CONFIRMED bookings', sql(`SELECT count(*) FROM (SELECT "seatId" FROM "Booking" WHERE status='CONFIRMED' GROUP BY 1 HAVING count(*) > 1) d`) === '0');
  check('no seat has two live holds', sql(`SELECT count(*) FROM (SELECT "seatId" FROM "Booking" WHERE status='HELD' AND "expiresAt" > now() GROUP BY 1 HAVING count(*) > 1) d`) === '0');
  check('no seat is both booked and held', sql(`SELECT count(*) FROM "Booking" h JOIN "Booking" c ON c."seatId" = h."seatId" AND c.status = 'CONFIRMED' WHERE h.status = 'HELD' AND h."expiresAt" > now()`) === '0');
} finally {
  try { sh('docker compose unpause redis'); } catch {}
  try { sh('docker compose start redis'); } catch {}
  sql(`DELETE FROM "Booking" WHERE "seatId" IN (SELECT id FROM "Seat" WHERE "eventId" = ${eventId})`);
  sql(`DELETE FROM "Event" WHERE id = ${eventId}`);
  try { sh(`docker compose exec -T redis sh -c "redis-cli --scan --pattern 'hold:{event:${eventId}}:*' | xargs -r redis-cli DEL"`); } catch {}
  console.log(`\nCleaned up event ${eventId}.`);
}

console.log(`${failures === 0 ? 'All checks passed' : `${failures} check(s) failed`}`);
process.exit(failures ? 1 : 0);

